function readDB(){
  if(!fs.existsSync(DB_FILE)){
    const seed = { products: SAMPLE_PRODUCTS, customers: SAMPLE_CUSTOMERS, sales: [] };
    fs.writeFileSync(DB_FILE, JSON.stringify(seed, null, 2));
    return seed;
  }
  try{
    return JSON.parse(fs.readFileSync(DB_FILE, "utf-8"));
  }catch(e){
    return { products: SAMPLE_PRODUCTS, customers: SAMPLE_CUSTOMERS, sales: [] };
  }
}
function writeDB(db){
  fs.writeFileSync(DB_FILE, JSON.stringify(db, null, 2));
}

function ensureBillsDir(){
  if(!fs.existsSync(BILLS_DIR)) fs.mkdirSync(BILLS_DIR, { recursive: true });
}

function listBills(){
  ensureBillsDir();
  return fs.readdirSync(BILLS_DIR)
    .filter(f=> f.endsWith(".html"))
    .map(f=>{
      const stat = fs.statSync(path.join(BILLS_DIR, f));
      return { orderId: f.replace(/\.html$/, ""), savedAt: stat.mtime.toISOString(), sizeBytes: stat.size };
    })
    .sort((a,b)=> new Date(b.savedAt) - new Date(a.savedAt));
}

// Only allow safe order-id-style filenames — letters, numbers, dashes,
// underscores — to prevent any path traversal via a crafted orderId.
const SAFE_ID = /^[A-Za-z0-9_-]{1,80}$/;

